From d7434e15f3e8e4f7656589dafac026b378443c4d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:55:49 +0100
Subject: [PATCH] session-restore: Keep windows saved by a cancelled logout

When an app cancelled the logout, the windows already closed by it were
lost, as the next logout saved the session again from scratch. Logouts
now add to what an earlier one of the same session saved instead.

BUG: 501472
---
 startkde/plasma-shutdown/shutdown.cpp |  2 +-
 startkde/session-restore/restore.cpp  |  7 +++++--
 startkde/session-restore/save.cpp     | 25 +++++++++++++++++++++----
 3 files changed, 27 insertions(+), 7 deletions(-)

diff --git a/startkde/plasma-shutdown/shutdown.cpp b/startkde/plasma-shutdown/shutdown.cpp
index af56314186..c3e35e764c 100644
--- a/startkde/plasma-shutdown/shutdown.cpp
+++ b/startkde/plasma-shutdown/shutdown.cpp
@@ -103,7 +103,7 @@ void Shutdown::ksmServerComplete()

     if (c.readEntry("loginMode", "restorePreviousLogout") == QLatin1String("restorePreviousLogout")) {
         // Now record windows that are not session managed
-        int ret = QProcess::execute(QStringLiteral(PLASMA_FALLBACK_SESSION_SAVE_BIN));
+        int ret = QProcess::execute(QStringLiteral(PLASMA_FALLBACK_SESSION_SAVE_BIN), {QStringLiteral("--logout")});
         if (ret) {
             qCWarning(PLASMA_SESSION) << "plasma-fallback-session-save failed with return code" << ret;
         }
diff --git a/startkde/session-restore/restore.cpp b/startkde/session-restore/restore.cpp
index d73b83831e..233cedbc56 100644
--- a/startkde/session-restore/restore.cpp
+++ b/startkde/session-restore/restore.cpp
@@ -27,13 +27,16 @@ int main(int argc, char *argv[])
     QGuiApplication a(argc, argv);
     a.setApplicationName(u"plasmasessionrestore"_s);

+    KSharedConfig::Ptr config = KSharedConfig::openStateConfig();
+    // A new session starts, so the next logout replaces the saved windows
+    config->deleteGroup(u"General"_s);
+    config->sync();
+
     SMServerSettings ksmserverSettings;
     if (ksmserverSettings.loginMode() == SMServerSettings::emptySession) {
         return EXIT_SUCCESS;
     }

-    KSharedConfig::Ptr config = KSharedConfig::openStateConfig();
-
     QList<KJob *> jobs;
     QEventLoop e;

diff --git a/startkde/session-restore/save.cpp b/startkde/session-restore/save.cpp
index 7cd20f4cf0..641db38848 100644
--- a/startkde/session-restore/save.cpp
+++ b/startkde/session-restore/save.cpp
@@ -49,13 +49,30 @@ int main(int argc, char *argv[])
     }

     KSharedConfig::Ptr config = KSharedConfig::openStateConfig();
+    KConfigGroup generalGroup = config->group(u"General"_s);
+
+    const bool logout = a.arguments().contains(u"--logout"_s);
+    QSet<QString> seenAppIds;
+    int firstGroup = 0;

     const QStringList groupList = config->groupList();
-    for (const QString &group : groupList) {
-        config->deleteGroup(group);
+    if (logout && generalGroup.readEntry("savedAtLogout", false)) {
+        // An earlier logout of this session was cancelled after closing some windows, keep what it saved
+        for (const QString &group : groupList) {
+            if (group != generalGroup.name()) {
+                seenAppIds.insert(config->group(group).readEntry("appId"));
+                firstGroup = std::max(firstGroup, group.toInt() + 1);
+            }
+        }
+    } else {
+        for (const QString &group : groupList) {
+            config->deleteGroup(group);
+        }
+    }
+    if (logout) {
+        generalGroup.writeEntry("savedAtLogout", true);
     }

-    QSet<QString> seenAppIds;
     for (int i = 0; i < tasksModel.rowCount(); ++i) {
         const QModelIndex index = tasksModel.index(i, 0);
         QString appId = tasksModel.data(index, TaskManager::AbstractTasksModel::StorageId).toString();
@@ -80,7 +97,7 @@ int main(int argc, char *argv[])
             continue;
         }

-        auto group = config->group(QString::number(i));
+        auto group = config->group(QString::number(firstGroup + i));
         qCDebug(FALLBACK_SESSION_RESTORE) << "Saving" << group.name() << appId;
         group.writeEntry("appId", appId);
         seenAppIds.insert(appId);
-- 
